typedef float time_value_t;
struct stringx { void *data; int length; };

class input_device
{
public:
    virtual stringx get_name() const = 0;
    virtual stringx get_name(int axis) const = 0;
    virtual int get_id() const = 0;
    virtual int get_axis_count() const = 0;
    virtual int get_axis_id(int axis) const = 0;
    virtual float get_axis_state(int axis, int control_axis) const = 0;
    virtual float get_axis_old_state(int axis, int control_axis) const = 0;
    virtual float get_axis_delta(int axis, int control_axis) const = 0;
    virtual bool is_connected() const { return false; }
};

class input_mgr
{
    char padding[40];
    input_device *joystick_devices[9];
public:
    static input_mgr *inst();
    inline input_device *get_joystick_index(int index) const
    {
        return joystick_devices[index];
    }
};
extern input_mgr *input_manager;
inline input_mgr *input_mgr::inst() { return input_manager; }

class FEMenuEntry
{
public:
    int entry_num;
    void Disable(bool disabled);
};

class TextString
{
public:
    void Update(float time_inc);
};

class PanelQuad;

class FEGraphicalMenu
{
    char padding0[0x4c];
protected:
    FEMenuEntry *highlighted;
private:
    char padding1[0x100];
public:
    void Update(float time_inc);
    void setHigh(FEMenuEntry *entry, bool anim = true);
};

class OptionsMenu : public FEGraphicalMenu
{
public:
    enum { OpScoreEntry, OpRumble1Entry, OpRumble2Entry, OpRumble3Entry,
           OpRumble4Entry, OpStereoEntry, OpMasterEntry, OpAmbientEntry,
           OpSFXEntry, OpVoiceEntry, OpMusicEntry, OpEnd };
private:
    static const int MAX_VOLUME = 10;
    static const int NUM_VOLUME = 5;
    static const int first_vol = OpMasterEntry;
    static const int num_switches = OpStereoEntry;
    PanelQuad *levels[NUM_VOLUME][MAX_VOLUME];
    PanelQuad *lights[OpEnd];
    PanelQuad *back;
    float rumbleTimer[4];
    int stereo_op;
    TextString *stereo_text[3];
    TextString *switch_text[num_switches][2];
    TextString *options_text;
    TextString *slevels_text;
    int volumes[NUM_VOLUME];
    FEMenuEntry *options_list[OpEnd];
    bool switches[num_switches];
public:
    void Update(time_value_t time_inc);
private:
    void RumbleOn(bool on, int controller);
};

#define RUMBLETIME .15f

__asm__(".equ input_manager, 0x0046B7B0");
__asm__(".equ Disable__11FEMenuEntryb, 0x00155E68");
__asm__(".equ Update__10TextStringf, 0x001482F8");
__asm__(".equ setHigh__6FEMenuP11FEMenuEntryb, 0x00156638");
__asm__(".equ Update__15FEGraphicalMenuf, 0x001DB100");
__asm__(".equ RumbleOn__11OptionsMenubi, 0x00182E20");

void OptionsMenu::Update(time_value_t time_inc)
{
	int i;


	// Update rumble status
	for( int j = 0; j < 4; j++ )
	{
		input_device* joy = input_mgr::inst()->get_joystick_index( j );
		if( joy && joy->is_connected() )
			options_list[ OpRumble1Entry + j ]->Disable( false );
		else
		{
			if (highlighted == options_list[ OpRumble1Entry + j ])
				setHigh(options_list[OpScoreEntry]);
			options_list[ OpRumble1Entry + j ]->Disable( true );
		}
	}

	options_text->Update(time_inc);
	slevels_text->Update(time_inc);
	stereo_text[stereo_op]->Update(time_inc);

	for (i=0; i < 4; i++)
		if (rumbleTimer[i] >= 0)
		{
			rumbleTimer[i] += time_inc;
			if (rumbleTimer[i] > RUMBLETIME)
				RumbleOn(false, i);
		}

	for(i=0; i<num_switches; i++)
		switch_text[i][switches[i]]->Update(time_inc);
	FEGraphicalMenu::Update(time_inc);
}
